'use client';

import * as React from 'react';
import { Toast } from '@base-ui/react/toast';
import { Kbd } from '../kbd/kbd';
import './toast.css';

/* ─────────────────────────────────────────────────────────
 * TOAST (KAMUI-20) on Base UI Toast
 *   show     one at a time; arrives one nest from below from .97 on settle
 *   undo     a cap with ⌘Z; the toast stays 5 s (plain 2.6 s); errors stay until resolved
 *   leave    on release, the way it came (a crossfade under Reduce Motion)
 * Toasts are for a person's own actions with Undo, never for recognition.
 * ───────────────────────────────────────────────────────── */

export type ToastTone = 'default' | 'success' | 'error';

export interface ToastOptions {
  /** What happened, as the person would say it: "Moved 3 blocks", "Pinned as a live region". */
  title: string;
  /** A short detail after a middle dot: "it updates as you write". */
  sub?: string;
  /** Undo the action. Adds the Undo cap and keeps the toast 5 s. */
  undo?: () => void;
  /** success carries its check; error stays until resolved. */
  tone?: ToastTone;
  /** Override how long it stays, in ms (0: until dismissed). */
  timeout?: number;
}

const ms = (name: string, fallback: number) =>
  typeof window === 'undefined' ? fallback : parseFloat(getComputedStyle(document.documentElement).getPropertyValue(name)) || fallback;

/** Shows toasts. Call show() from anywhere under a ToastProvider. */
export function useToast() {
  const manager = Toast.useToastManager();
  return React.useMemo(() => ({
    show({ title, sub, undo, tone = 'default', timeout }: ToastOptions) {
      return manager.add({
        title,
        description: sub,
        type: tone,
        timeout: timeout ?? (tone === 'error' ? 0 : undo ? ms('--mu-toast-undo-ms', 5000) : ms('--mu-toast-plain-ms', 2600)),
        actionProps: undo ? { onClick: undo } : undefined,
      });
    },
    dismiss: (id: string) => manager.close(id),
  }), [manager]);
}

function ToastList() {
  const { toasts } = Toast.useToastManager();
  return (
    <Toast.Portal>
      <Toast.Viewport className="mu-toast-viewport">
        {toasts.map((t) => (
          <Toast.Root key={t.id} toast={t} className="mu-toast type-ui" data-type={t.type}>
            <span className="mu-toast-text">
              {t.type === 'success' && <span aria-hidden className="mu-toast-check">✓</span>}
              <Toast.Title render={<span />}>{t.title}</Toast.Title>
              {t.description && <Toast.Description render={<span className="mu-toast-sub" />}>· {t.description}</Toast.Description>}
            </span>
            {t.actionProps && (
              <Toast.Action className="mu-toast-undo type-ui" aria-keyshortcuts="Meta+Z">
                Undo <Kbd surface="sunk">⌘Z</Kbd>
              </Toast.Action>
            )}
          </Toast.Root>
        ))}
      </Toast.Viewport>
    </Toast.Portal>
  );
}

/** Put once near the root: the toast region at the bottom centre, one toast at a time. */
export function ToastProvider({ children }: { children: React.ReactNode }) {
  return (
    <Toast.Provider limit={1}>
      {children}
      <ToastList />
    </Toast.Provider>
  );
}

@import "../tokens.css";
@import "../kbd/kbd.css";

/* Toast (KAMUI-20; Kamui 04 §12) on Base UI Toast. */
.mu-toast-viewport {
  position: fixed;
  left: 50%;
  bottom: var(--mu-toast-bottom);
  z-index: 50;
  transform: translateX(-50%);
  display: flex;
  flex-direction: column;
  align-items: center;
  outline: none;
}
.mu-toast {
  display: flex;
  align-items: center;
  gap: var(--mu-toast-gap);
  height: var(--mu-toast-height);
  padding: 0 var(--mu-toast-pad-end) 0 var(--mu-toast-pad-start);
  border-radius: 999px;
  white-space: nowrap;
  color: var(--mu-toast-ink);
  background: var(--mu-toast-bg);
  box-shadow: var(--mu-toast-sh);
  -webkit-backdrop-filter: var(--mu-backdrop);
  backdrop-filter: var(--mu-backdrop);
  /* Arrives one nest from below from .97 on settle; leaves the way it came on release. */
  transition:
    opacity var(--mu-spring-settle-d) var(--mu-spring-settle),
    transform var(--mu-spring-settle-d) var(--mu-spring-settle);
}
.mu-toast:not(:has(.mu-toast-undo)) { padding-right: var(--mu-toast-pad-start); }
.mu-toast[data-starting-style] {
  opacity: 0;
  transform: translateY(calc(var(--mu-toast-enter-rise) * var(--mu-travel-settle))) scale(calc(1 - (1 - var(--mu-toast-enter-scale)) * var(--mu-travel-settle)));
}
.mu-toast[data-ending-style] {
  opacity: 0;
  transform: translateY(calc(var(--mu-toast-enter-rise) * var(--mu-travel-release))) scale(calc(1 - (1 - var(--mu-toast-enter-scale)) * var(--mu-travel-release)));
  transition-duration: var(--mu-spring-release-d);
  transition-timing-function: var(--mu-spring-release);
}
@media (prefers-reduced-transparency: reduce) { .mu-toast { background: var(--mu-frost-graphite-opaque); -webkit-backdrop-filter: none; backdrop-filter: none; } }
.mu-toast-text { display: inline-flex; align-items: center; gap: 6px; }
.mu-toast-sub { color: var(--mu-toast-sub); }
.mu-toast-check { color: var(--mu-success); }
.mu-toast[data-type="error"] .mu-toast-mark { color: var(--mu-red); }
.mu-toast-undo {
  display: inline-flex;
  align-items: center;
  gap: var(--mu-toast-undo-gap);
  height: var(--mu-toast-undo-height);
  padding: 0 var(--mu-toast-undo-pad-end) 0 var(--mu-toast-undo-pad-start);
  border: 0;
  border-radius: 999px;
  color: inherit;
  background: var(--mu-toast-undo-bg);
  box-shadow: var(--mu-toast-undo-sh);
  cursor: pointer;
  transition: transform var(--mu-spring-release-d) var(--mu-spring-release);
}
.mu-toast-undo:active { transform: translateY(var(--mu-motion-press)); transition-duration: 50ms; }
.mu-toast-undo:focus-visible { outline: var(--mu-focus-width) solid var(--mu-green); outline-offset: var(--mu-focus-offset); }
